def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) >= bid:
                    strong_prev.append(bid)

    if not alive:
        safe = 18.0 if hp > 3 else 40.0
        return float(max(0.0, min(budget, safe)))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    need = 0.0
    if hp <= 2:
        need += 0.75
    elif hp <= 4:
        need += 0.4
    if no_water >= 2:
        need += 0.6
    elif no_water >= 1:
        need += 0.25
    if day >= 8:
        need += 0.15

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_affordable = max(strong_prev) if strong_prev else highest_prev

    base = 24.0 + 34.0 * scarcity + 18.0 * need

    if supply >= 23:
        bid = min(base, 38.0 + 8.0 * need)
    elif supply >= 20:
        bid = base
    elif supply >= 17:
        bid = base + 8.0
    else:
        bid = base + 18.0

    if need >= 0.7:
        target = strongest_affordable + 2.5
        if target > bid:
            bid = target
    elif scarcity >= 0.7 and strongest_affordable < 110:
        target = strongest_affordable + 1.5
        if target > bid:
            bid = target
    elif highest_prev >= 110 and need < 0.7:
        bid = min(bid, 62.0)

    reserve_floor = 0.0
    if hp > 3 and no_water == 0:
        reserve_floor = max(0.0, budget - 9.0 * DAILY_SALARY * 0.55)
    max_today = budget - reserve_floor
    if max_today < 0:
        max_today = budget

    if hp <= 2 or no_water >= 2:
        max_today = budget
        bid = max(bid, 72.0 + 18.0 * scarcity)

    bid = min(bid, max_today, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Estimate opponent pressure
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        second_prev = 0.0
        avg_prev = 0.0

    # Base bid target: aim to slightly undercut the highest consistent survival bids
    # If opponents were bidding high, we raise; if not, we conserve.
    pressure = 0.0
    if highest_prev > 0:
        pressure = min(1.0, highest_prev / (DAILY_SALARY * 0.9))

    # HP urgency: bid more when low HP or accumulating no-water days
    urgency = 0.0
    if my_hp <= 2.0:
        urgency = 1.0
    elif my_hp <= 4.0:
        urgency = 0.7
    elif my_hp <= 6.0:
        urgency = 0.4
    else:
        urgency = 0.2

    if my_no_water_days >= 2:
        urgency = min(1.0, urgency + 0.25)

    # Supply scaling: higher supply reduces need to outbid heavily
    # (more water likely means easier to secure enough allocation)
    supply_factor = 0.0
    if supply <= float(MIN_SUPPLY):
        supply_factor = 1.0
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.6
    else:
        # linear between MIN_SUPPLY and MAX_SUPPLY
        supply_factor = 1.0 - 0.4 * ((supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY)))

    # Target bid computation
    # Try to be competitive but not maxing budget.
    # Use avg/second as a proxy for typical bids.
    typical = avg_prev if avg_prev > 0 else DAILY_SALARY * 0.55
    competitive_floor = max(DAILY_SALARY * 0.35, second_prev * 0.9)

    target = competitive_floor
    target += (pressure * 0.25 + urgency * 0.55) * (highest_prev if highest_prev > 0 else DAILY_SALARY * 0.6)
    target *= supply_factor

    # Clamp to reasonable range relative to our budget
    # Never exceed budget; also avoid wasting when budget is low.
    min_bid = 0.0
    max_bid = max(0.0, my_budget)

    # If budget is very low, prioritize survival: bid up to 85% of budget when urgency is high
    if max_bid <= DAILY_SALARY * 0.25:
        if urgency >= 0.7:
            return max(min_bid, min(max_bid, max_bid * 0.85))
        return max(min_bid, min(max_bid, max_bid * 0.55))

    # Otherwise, cap at ~70% of daily salary to conserve across days
    cap = DAILY_SALARY * (0.7 if urgency < 0.7 else 0.95)
    final_bid = min(max_bid, min(cap, target))

    # Ensure some minimal bid to avoid being completely outbid when pressure is high
    if highest_prev > DAILY_SALARY * 0.6:
        final_bid = max(final_bid, min(max_bid, DAILY_SALARY * 0.45 + urgency * DAILY_SALARY * 0.2))

    return float(max(min_bid, final_bid))
